create extension if not exists pgcrypto;
create type public.workspace_role as enum('owner','admin','manager','publisher','analyst','client_approver');
create type public.job_state as enum('queued','claimed','dispatching','succeeded','retryable','failed','needs_review','cancelled');
create table public.workspaces(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 2 and 120),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.workspace_members(workspace_id uuid references public.workspaces(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role public.workspace_role not null,created_at timestamptz not null default now(),primary key(workspace_id,user_id));
create table public.brands(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,timezone text not null default 'UTC',voice_profile jsonb not null default '{}',created_at timestamptz not null default now(),unique(workspace_id,id));
create table public.social_accounts(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,brand_id uuid not null,provider text not null check(provider in('facebook','instagram','tiktok','youtube','linkedin','x','whatsapp')),provider_account_id text not null,display_name text,connection_state text not null default 'pending',granted_scopes text[] not null default '{}',capabilities jsonb not null default '{}',token_secret_ref text,created_at timestamptz not null default now(),unique(provider,provider_account_id),foreign key(workspace_id,brand_id) references public.brands(workspace_id,id) on delete cascade);
create table public.content_items(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,brand_id uuid not null,created_by uuid not null references auth.users(id),title text not null default '',body text not null default '',media_refs jsonb not null default '[]',status text not null default 'draft' check(status in('draft','in_review','approved','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(workspace_id,brand_id) references public.brands(workspace_id,id) on delete cascade);
create table public.publishing_jobs(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,brand_id uuid not null,content_id uuid not null references public.content_items(id) on delete cascade,social_account_id uuid not null references public.social_accounts(id) on delete cascade,scheduled_at timestamptz not null,state public.job_state not null default 'queued',idempotency_key text not null unique,attempts int not null default 0 check(attempts>=0),max_attempts int not null default 5 check(max_attempts between 1 and 10),lease_owner text,lease_expires_at timestamptz,provider_post_id text,last_error_code text,last_error_safe text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(workspace_id,brand_id) references public.brands(workspace_id,id) on delete cascade);
create index publishing_jobs_due_idx on public.publishing_jobs(scheduled_at) where state in('queued','retryable');
create table public.audit_events(id bigint generated always as identity primary key,workspace_id uuid not null references public.workspaces(id) on delete cascade,actor_user_id uuid references auth.users(id) on delete set null,event_type text not null,resource_type text not null,resource_id text,outcome text not null,safe_metadata jsonb not null default '{}',created_at timestamptz not null default now());
create or replace function public.is_workspace_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.workspace_members m where m.workspace_id=target and m.user_id=auth.uid()) $$;
revoke all on function public.is_workspace_member(uuid) from public;grant execute on function public.is_workspace_member(uuid) to authenticated;
alter table public.workspaces enable row level security;alter table public.workspace_members enable row level security;alter table public.brands enable row level security;alter table public.social_accounts enable row level security;alter table public.content_items enable row level security;alter table public.publishing_jobs enable row level security;alter table public.audit_events enable row level security;
create policy workspace_member_read on public.workspaces for select to authenticated using(public.is_workspace_member(id));
create policy members_read on public.workspace_members for select to authenticated using(user_id=auth.uid() or public.is_workspace_member(workspace_id));
create policy brands_read on public.brands for select to authenticated using(public.is_workspace_member(workspace_id));
create policy brands_insert_admin on public.brands for insert to authenticated with check(exists(select 1 from public.workspace_members m where m.workspace_id=workspace_id and m.user_id=auth.uid() and m.role in('owner','admin')));
create policy accounts_read on public.social_accounts for select to authenticated using(public.is_workspace_member(workspace_id));
create policy content_read on public.content_items for select to authenticated using(public.is_workspace_member(workspace_id));
create policy content_insert on public.content_items for insert to authenticated with check(public.is_workspace_member(workspace_id) and created_by=auth.uid());
create policy content_update on public.content_items for update to authenticated using(public.is_workspace_member(workspace_id)) with check(public.is_workspace_member(workspace_id));
create policy jobs_read on public.publishing_jobs for select to authenticated using(public.is_workspace_member(workspace_id));
create policy audit_admin_read on public.audit_events for select to authenticated using(exists(select 1 from public.workspace_members m where m.workspace_id=workspace_id and m.user_id=auth.uid() and m.role in('owner','admin')));
-- No browser write policies for credentials, publishing jobs or audit events. Trusted server operations must validate roles.
